    // Yandex: ll= / pt= / whatshere[point]= are «longitude,latitude»
    if ((m = /(?:[?&](?:ll|pt|whatshere\[point\])=)(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/.exec(s)) && /yandex|ya\.ru/.test(s)) return ok(m[2], m[1]);
