    if (/2gis/.test(s) && (m = /(?:\/geo\/|[?&]m=)(-?\d+(?:\.\d+)?)(?:,|%2C)(-?\d+(?:\.\d+)?)/.exec(s))) return ok(m[2], m[1]);
