    var t2 = s.replace(/[°NnEeСсВв]/g, " ").replace(/(\d),(\d)/g, "$1.$2");
    if ((m = /^\s*(-?\d{1,2}(?:\.\d+)?)[\s,;]+(-?\d{1,3}(?:\.\d+)?)\s*$/.exec(t2))) return ok(m[1], m[2]);
    return null;
